const $=id=>document.getElementById(id),money=['gross','paid','duplicate','compensation','recovery'],kinds=['invoice','payment','compensation','recovery'];
let epoch=0,incident=null,version=0,refs=[],last=null,loading=false;
const element=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};
const minor=(value,scale)=>{if(!value.trim())return null;if(!/^(0|[1-9]\d*)(\.\d+)?$/.test(value))throw Error('金额必须是非负十进制数');const [whole,part='']=value.split('.');if(part.length>scale)throw Error('金额超过所选精度');return BigInt(whole+part.padEnd(scale,'0')).toString();};
const major=(value,scale)=>{if(value===null)return '未知';if(!scale)return value;const s=value.padStart(scale+1,'0');return s.slice(0,-scale)+'.'+s.slice(-scale);};
function clear(){epoch++;incident=null;$('summary').replaceChildren();$('incidents').replaceChildren();$('selected').textContent='请选择事故';$('expense').hidden=true;$('mapping').hidden=true;$('coverage').textContent='';}
async function api(path,options={}){const token=sessionStorage.getItem('incident-session');if(!token)throw Error('请先在时间线页面登录');const response=await fetch('/api/incidents-v1'+path,{...options,headers:{Authorization:'Bearer '+token,...(options.body?{'Content-Type':'application/json'}:{}),...(options.key?{'Idempotency-Key':options.key}:{})}});const data=await response.json();if(!response.ok){if(response.status===401){sessionStorage.removeItem('incident-session');clear();}throw Error(data.error);}return data;}
async function guard(fn){try{await fn();}catch(e){$('status').textContent=e.message;}}
function fresh(){version=0;last=null;$('expense-id').value=crypto.randomUUID();$('version').textContent='新明细 · 版本 1';for(const k of money)$(k).value='';$('voucher').value='';$('reason').value='';$('verification').value='pending';for(const k of kinds)for(const option of $(k+'-ref').options)option.selected=false;}
function edit(line){version=line.version;$('expense-id').value=line.expenseId;$('version').textContent=`基于版本 ${version} 追加更正`;for(const id of ['category','currency','scale','verification','reason'])$(id).value=line[id];$('voucher').value=line.voucherRef;for(const k of money)$(k).value=line[k]===null?'':major(line[k],line.scale);for(const k of kinds){const select=$(k+'-ref'),values=line.evidenceRefs.filter(r=>r.kind===k).map(r=>`${r.importId}/${r.objectId}`);for(const value of values)if(![...select.options].some(o=>o.value===value)){const option=element('option',value+' · 历史引用（当前不可用，需核对）');option.value=value;select.append(option);}for(const option of select.options)option.selected=values.includes(option.value);}last=null;}
async function show(id){const current=++epoch,project=$('project').value;incident=null;$('expense').hidden=true;$('mapping').hidden=true;$('summary').replaceChildren();$('coverage').textContent='';const data=await api(`/incidents/${id}/expenses?projectId=${encodeURIComponent(project)}`),info=await api(`/incidents/${id}?projectId=${encodeURIComponent(project)}`);const timelines=await Promise.all(info.runIds.map(run=>api(`/runs/${run}/timeline?projectId=${encodeURIComponent(project)}`)));if(current!==epoch)return;incident=id;refs=timelines.flatMap(t=>t.materials).filter(m=>!['missing','unavailable-or-corrupt'].includes(m.status));
 for(const kind of kinds){const select=$(kind+'-ref');select.replaceChildren();const seen=new Set();for(const ref of refs){const value=`${ref.importId}/${ref.objectId}`;if(seen.has(value))continue;seen.add(value);const option=element('option',ref.path+' · '+ref.objectId);option.value=value;select.append(option);}}
 $('selected').textContent=info.statement;$('summary').append(element('h2','净损失汇总'));for(const g of data.totals)$('summary').append(element('p',`${g.currency}（${g.scale}位，${g.dataClass}）净额 ${major(g.netTotal,g.scale)}；已知部分 ${major(g.knownSubtotal,g.scale)}；未知明细 ${g.unknownCount}`));for(const r of data.rows){const p=element('p',`${r.line.expenseId} v${r.line.version} · ${r.synthetic?'合成材料':'材料待核实'} · 计入净额 ${major(r.countedNet,r.line.scale)} ${r.line.currency} · ${r.issues.join(', ')||'算术核对通过，非保险批准'}`);const b=element('button','更正 '+r.line.expenseId);b.onclick=()=>edit(r.line);p.append(b);$('summary').append(p);}$('summary').append(element('p',`保留历史版本 ${data.history.length} 条。`));$('expense').hidden=false;$('mapping').hidden=false;fresh();$('status').textContent='费用已加载';}
$('project').value=sessionStorage.getItem('incident-project')||'';$('project').oninput=clear;
$('load').onsubmit=e=>{e.preventDefault();guard(async()=>{clear();const current=epoch,project=$('project').value;let cursor='0',items=[];do{const page=await api(`/incidents?projectId=${encodeURIComponent(project)}&cursor=${cursor}`);if(current!==epoch)return;items.push(...page.items);cursor=page.nextCursor;}while(cursor);for(const i of items){const b=element('button',i.incidentId+' · '+i.statement);b.onclick=()=>guard(()=>show(i.incidentId));$('incidents').append(b);}$('status').textContent=`${items.length} 起事故`;});};
$('new').onclick=fresh;
$('expense').onsubmit=e=>{e.preventDefault();if(loading)return;guard(async()=>{const id=incident,scale=Number($('scale').value),body={projectId:$('project').value,expenseId:$('expense-id').value,expectedVersion:version,category:$('category').value,currency:$('currency').value,scale,voucherRef:$('voucher').value,evidenceRefs:[],verification:$('verification').value,reason:$('reason').value};for(const k of money)body[k]=minor($(k).value,scale);for(const kind of kinds)for(const option of $(kind+'-ref').selectedOptions){const [importId,objectId]=option.value.split('/');body.evidenceRefs.push({importId,objectId,kind});}const serialized=JSON.stringify(body);if(last?.body!==serialized)last={body:serialized,key:crypto.randomUUID()};loading=true;$('save').disabled=true;const current=epoch;try{await api(`/incidents/${id}/expenses`,{method:'POST',body:serialized,key:last.key});if(current===epoch){await show(id);$('status').textContent='新版本已保存并重新核算';}}finally{loading=false;$('save').disabled=false;}});};
$('terms').onsubmit=e=>{e.preventDefault();guard(async()=>{const current=epoch,scale=Number($('scale').value),terms={mode:'local_test',termsVersion:$('terms-version').value,currency:$('currency').value,scale,deductible:minor($('deductible').value,scale),shareNumerator:$('numerator').value,shareDenominator:$('denominator').value,incidentLimit:minor($('limit').value,scale),annualRemaining:minor($('remaining').value,scale)};const result=await api(`/incidents/${incident}/expenses/local-test`,{method:'POST',body:JSON.stringify({projectId:$('project').value,terms})});if(current===epoch)$('coverage').textContent=`本地测试 ${terms.termsVersion}：拟议金额 ${major(result.proposedAmount,scale)} ${terms.currency}，未创建赔案或付款。`;});};
$('logout').onclick=()=>guard(async()=>{try{await api('/session',{method:'DELETE'});}finally{sessionStorage.removeItem('incident-session');clear();$('status').textContent='已退出';}});

